# ---------------------------------------------------------------- ipv6 text

_HEX = frozenset('0123456789abcdefABCDEF')
_ALLOWED = frozenset('0123456789abcdefABCDEF:')
_DEC = frozenset('0123456789')

_parse_cache = {}


def parse_ipv6(s):
    """Strict colon separated hexadecimal notation.  Returns int or None."""
    if not is_str(s):
        return None
    r = _parse_cache.get(s)
    if r is not None:
        return r[0] if r[0] is not None else None
    v = _parse_ipv6(s)
    if len(_parse_cache) < 150000:
        _parse_cache[s] = (v,)
    return v


def _parse_ipv6(s):
    n = len(s)
    if n == 0 or n > 39:
        return None
    for ch in s:
        if ch not in _ALLOWED:
            return None
    i = s.find('::')
    if i >= 0:
        if s.find('::', i + 1) >= 0:
            return None
        head = s[:i]
        tail = s[i + 2:]
        left = head.split(':') if head else []
        right = tail.split(':') if tail else []
        cnt = len(left) + len(right)
        if cnt > 7:
            return None
        for g in left:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        for g in right:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        groups = left + ['0'] * (8 - cnt) + right
    else:
        groups = s.split(':')
        if len(groups) != 8:
            return None
        for g in groups:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
    v = 0
    for g in groups:
        v = (v << 16) | int(g, 16)
    return v


